import { GoogleGenerativeAI } from "@google/generative-ai";

export function getClient(): GoogleGenerativeAI {
    // We check for GEMINI_API_KEY. If they still have ANTHROPIC_API_KEY set, we'll try to use it as a fallback in case they named their key that during migration.
    const key = process.env.GEMINI_API_KEY || process.env.ANTHROPIC_API_KEY;
    if (!key) throw new Error("GEMINI_API_KEY is not set in environment variables");
    return new GoogleGenerativeAI(key);
}

export async function askClaude(
    systemPrompt: string,
    userMessage: string,
    jsonMode = false
): Promise<string> {
    try {
        const model = getClient().getGenerativeModel({
            model: "gemini-1.5-flash",
            systemInstruction: jsonMode
                ? systemPrompt +
                "\n\nCRITICAL: Respond with valid JSON only. " +
                "No markdown fences, no explanation text, no preamble."
                : systemPrompt,
        });

        const result = await model.generateContent({
            contents: [{ role: "user", parts: [{ text: userMessage }] }],
            generationConfig: {
                maxOutputTokens: 1024,
                responseMimeType: jsonMode ? "application/json" : "text/plain",
            },
        });

        return result.response.text();
    } catch (error) {
        console.error("Gemini API error:", error);
        throw new Error("AI service temporarily unavailable");
    }
}

export async function askClaudeWithImage(
    systemPrompt: string,
    imageBase64: string,
    mediaType: "image/jpeg" | "image/png" | "image/webp" = "image/jpeg"
): Promise<string> {
    try {
        const model = getClient().getGenerativeModel({
            model: "gemini-1.5-flash",
        });

        // Strip data URI prefix if present
        const base64Data = imageBase64.replace(/^data:image\/\w+;base64,/, "");

        const parts = [
            {
                inlineData: {
                    data: base64Data,
                    mimeType: mediaType,
                },
            },
            { text: systemPrompt },
        ];

        const result = await model.generateContent({
            contents: [{ role: "user", parts }],
            generationConfig: {
                maxOutputTokens: 512,
            },
        });

        return result.response.text();
    } catch (error) {
        console.error("Gemini Vision API error:", error);
        throw new Error("AI image analysis temporarily unavailable");
    }
}
